def fetch(name):
    dest=root/name
    dest.parent.mkdir(parents=True,exist_ok=True)
    for i in range(4):
        try:
            data=urllib.request.urlopen("https://grf.robrowser.com/"+urllib.parse.quote(name),timeout=40).read()
            assert data and data[:1]!=b"<"
            dest.write_bytes(data)
            return
        except Exception:
            if i==3: raise
            time.sleep(2)
with ThreadPoolExecutor(6) as pool: list(pool.map(fetch, files))
